void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return; // No action needed if the descriptor is null or empty
    }

    if (descriptor.charAt(0) == '(') {
        // It's a method descriptor, parse the arguments
        int endOfArgumentsIndex = descriptor.indexOf(')');
        if (endOfArgumentsIndex == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        String argumentsPart = descriptor.substring(1, endOfArgumentsIndex);
        parseAndPopArguments(argumentsPart);
    } else {
        // It's a type descriptor, pop one type
        popType(descriptor);
    }
}

private void parseAndPopArguments(String argumentsPart) {
    int index = 0;
    while (index < argumentsPart.length()) {
        int consumed = popType(argumentsPart.substring(index));
        if (consumed == 0) {
            throw new IllegalArgumentException("Invalid type descriptor: " + argumentsPart.substring(index));
        }
        index += consumed;
    }
}

private int popType(String descriptorPart) {
    if (descriptorPart.startsWith("[")) {
        // Array type
        int arrayDepth = 0;
        while (descriptorPart.startsWith("[")) {
            arrayDepth++;
            descriptorPart = descriptorPart.substring(1);
        }
        if (descriptorPart.length() == 0) {
            return 0; // Invalid descriptor
        }
        // The element type of the array is now at the start of descriptorPart
        return arrayDepth + popType(descriptorPart);
    }

    switch (descriptorPart.charAt(0)) {
        case 'B': // byte
        case 'C': // char
        case 'D': // double (takes two slots)
        case 'F': // float
        case 'I': // int
        case 'J': // long (takes two slots)
        case 'S': // short
        case 'Z': // boolean
            return 1;
        case 'L':
            // Object type, e.g., Ljava/lang/String;
            int endOfClassDescriptor = descriptorPart.indexOf(';');
            if (endOfClassDescriptor == -1) {
                return 0; // Invalid descriptor
            }
            return endOfClassDescriptor + 1;
        default:
            return 0; // Unknown type
    }
}

