int function ( final CharSequence str , final int index , final int len ) {
    if ( str == null ) {
        throw new IllegalArgumentException( "CharSequence cannot be null" );
    }
    if ( index < 0 || len < 0 || index + len > str.length() ) {
        throw new IndexOutOfBoundsException( "Index or length is out of bounds" );
    }
    int size = 0;
    for ( int i = index; i < index + len; i++ ) {
        final char ch = str.charAt( i );
        if ( ch < 0x80 ) {
            size += 1;
        } else if ( ch < 0x800 ) {
            size += 2;
        } else if ( Character.isSurrogatePair( ch, str.charAt( i + 1 ) ) ) {
            size += 4;
            i++; // Skip the second surrogate character
        } else {
            size += 3;
        }
    }
    return size;
}

